// GENERIERT von office/n8n/bauen.mjs aus office/lib/*.js – nicht von Hand ändern.
// ===== office/lib/hash.js =====
// KI Office: SHA-256 und HMAC in reinem JavaScript.
// Warum nicht node:crypto? Derselbe Code läuft im n8n-Code-Knoten (dort ist require nicht überall erlaubt),
// im Browser (synchron, ohne Promise) und in Node. Die Tests vergleichen das Ergebnis mit node:crypto.

const K = [0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];

function utf8Bytes(s) {
  const str = String(s), out = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < str.length) { const d = str.charCodeAt(i + 1); if (d >= 0xdc00 && d <= 0xdfff) { c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00); i++; } }
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}

function sha256Bytes(bytes) {
  const l = bytes.length, bitLen = l * 8;
  const padded = bytes.slice(); padded.push(0x80);
  while (padded.length % 64 !== 56) padded.push(0);
  for (let i = 7; i >= 0; i--) padded.push(i >= 4 ? 0 : (bitLen >>> (i * 8)) & 0xff);
  const h = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const w = new Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < padded.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = (padded[off + i * 4] << 24) | (padded[off + i * 4 + 1] << 16) | (padded[off + i * 4 + 2] << 8) | padded[off + i * 4 + 3];
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (hh + S1 + ch + K[i] + w[i]) | 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) | 0;
      hh = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    h[0] = (h[0] + a) | 0; h[1] = (h[1] + b) | 0; h[2] = (h[2] + c) | 0; h[3] = (h[3] + d) | 0;
    h[4] = (h[4] + e) | 0; h[5] = (h[5] + f) | 0; h[6] = (h[6] + g) | 0; h[7] = (h[7] + hh) | 0;
  }
  const out = [];
  for (const x of h) out.push((x >>> 24) & 255, (x >>> 16) & 255, (x >>> 8) & 255, x & 255);
  return out;
}

const hex = bytes => bytes.map(b => b.toString(16).padStart(2, '0')).join('');

/** SHA-256 eines Textes (UTF-8) als Hex. */
function sha256(text) { return hex(sha256Bytes(utf8Bytes(text))); }

/** HMAC-SHA256(schluessel, nachricht) als Hex. */
function hmacSha256(schluessel, nachricht) {
  let k = utf8Bytes(schluessel);
  if (k.length > 64) k = sha256Bytes(k);
  while (k.length < 64) k.push(0);
  const ipad = k.map(b => b ^ 0x36), opad = k.map(b => b ^ 0x5c);
  return hex(sha256Bytes(opad.concat(sha256Bytes(ipad.concat(utf8Bytes(nachricht))))));
}

/** Kanonisches JSON: Schlüssel sortiert, damit derselbe Inhalt immer denselben Hash ergibt. */
function kanonisch(wert) {
  if (wert === null || typeof wert !== 'object') return JSON.stringify(wert === undefined ? null : wert);
  if (Array.isArray(wert)) return '[' + wert.map(kanonisch).join(',') + ']';
  return '{' + Object.keys(wert).sort().map(k => JSON.stringify(k) + ':' + kanonisch(wert[k])).join(',') + '}';
}

/** Inhalts-Hash für Freigaben: bindet eine Freigabe an exakt diesen Inhalt. */
function inhaltsHash(aktion, inhalt) { return sha256(kanonisch({ aktion: String(aktion || ''), inhalt: inhalt === undefined ? null : inhalt })); }

/** Vergleich in konstanter Zeit (gegen Timing-Angriffe bei Signaturen). */
function gleich(a, b) {
  a = String(a || ''); b = String(b || '');
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

// ===== office/lib/zustand.js =====
// KI Office: Zustandsmaschine für Agentenläufe (Runs).
// Diese Tabelle ist die einzige Quelle der Wahrheit. Sie steht wortgleich in docs/office/ARCHITEKTUR.md.
// „Technisch erfolgreich“ (status = abgeschlossen) ist strikt getrennt von „fachlich abgenommen“ (run.abgenommen = true, nur Menschen).

const STATUS = {
  WARTESCHLANGE: 'warteschlange',
  IN_ARBEIT: 'in_arbeit',
  WARTET_RUECKMELDUNG: 'wartet_rueckmeldung',
  WARTET_FREIGABE: 'wartet_freigabe',
  ABGESCHLOSSEN: 'abgeschlossen',
  FEHLGESCHLAGEN: 'fehlgeschlagen',
  ABGEBROCHEN: 'abgebrochen',
  UNBEKANNT: 'unbekannt'
};
const ALLE_STATUS = Object.values(STATUS);

const STATUS_TEXT = {
  warteschlange: 'Warteschlange',
  in_arbeit: 'in Arbeit',
  wartet_rueckmeldung: 'wartet auf Rückmeldung',
  wartet_freigabe: 'wartet auf Freigabe',
  abgeschlossen: 'abgeschlossen (technisch)',
  fehlgeschlagen: 'fehlgeschlagen',
  abgebrochen: 'abgebrochen',
  unbekannt: 'unbekannt / veraltet'
};

const ENDZUSTAENDE = ['abgeschlossen', 'fehlgeschlagen', 'abgebrochen', 'unbekannt'];
const istEndzustand = s => ENDZUSTAENDE.includes(s);

// Zulässige Übergänge: von → nach, durch wen (agent = ausführender Agent/Executor, mensch = Teammitglied, system = Wartung/Timeout), Anlass.
const UEBERGAENGE = [
  { von: 'warteschlange', nach: 'in_arbeit', wer: ['agent', 'system'], anlass: 'Executor meldet Start oder erstes Lebenszeichen' },
  { von: 'warteschlange', nach: 'fehlgeschlagen', wer: ['agent', 'system'], anlass: 'Start nicht möglich (Dispatch-Fehler)' },
  { von: 'warteschlange', nach: 'abgebrochen', wer: ['mensch'], anlass: 'Auftrag zurückgezogen' },
  { von: 'warteschlange', nach: 'unbekannt', wer: ['system'], anlass: 'Wartezeit überschritten, kein Executor hat übernommen' },
  { von: 'warteschlange', nach: 'wartet_freigabe', wer: ['system'], anlass: 'Guthaben des Agenten ist leer: der Start wird angehalten, bis Timo auffüllt und neu freigibt' },
  { von: 'in_arbeit', nach: 'wartet_rueckmeldung', wer: ['agent'], anlass: 'Agent stellt eine Rückfrage' },
  { von: 'in_arbeit', nach: 'wartet_freigabe', wer: ['agent'], anlass: 'Agent fordert Freigabe für eine externe Aktion an' },
  { von: 'in_arbeit', nach: 'abgeschlossen', wer: ['agent'], anlass: 'Ergebnis gemeldet (technisch erfolgreich, noch nicht abgenommen)' },
  { von: 'in_arbeit', nach: 'fehlgeschlagen', wer: ['agent', 'system'], anlass: 'Fehler gemeldet' },
  { von: 'in_arbeit', nach: 'abgebrochen', wer: ['mensch'], anlass: 'Mensch bricht ab (cancelRun)' },
  { von: 'in_arbeit', nach: 'unbekannt', wer: ['system'], anlass: 'Kein Lebenszeichen länger als timeout_sek (auch nach Neustart)' },
  { von: 'wartet_rueckmeldung', nach: 'in_arbeit', wer: ['mensch'], anlass: 'Mensch beantwortet die Rückfrage' },
  { von: 'wartet_rueckmeldung', nach: 'abgebrochen', wer: ['mensch'], anlass: 'Mensch bricht ab' },
  { von: 'wartet_rueckmeldung', nach: 'fehlgeschlagen', wer: ['agent', 'system'], anlass: 'Executor meldet Fehler' },
  { von: 'wartet_rueckmeldung', nach: 'unbekannt', wer: ['system'], anlass: 'Wartefrist für Menschen überschritten' },
  { von: 'wartet_freigabe', nach: 'in_arbeit', wer: ['mensch'], anlass: 'Freigabe erteilt oder abgelehnt (Agent entscheidet dann, wie es weitergeht)' },
  { von: 'wartet_freigabe', nach: 'warteschlange', wer: ['mensch'], anlass: 'Timo (Admin) gibt den Start eines Auftrags frei, den ein Teammitglied angelegt hat' },
  { von: 'wartet_freigabe', nach: 'abgebrochen', wer: ['mensch'], anlass: 'Mensch bricht ab, oder Timo lehnt den Start eines Auftrags ab' },
  { von: 'wartet_freigabe', nach: 'fehlgeschlagen', wer: ['agent', 'system'], anlass: 'Executor meldet Fehler' },
  { von: 'wartet_freigabe', nach: 'unbekannt', wer: ['system'], anlass: 'Wartefrist für Menschen überschritten' },
  { von: 'fehlgeschlagen', nach: 'warteschlange', wer: ['mensch', 'system'], anlass: 'Wiederholung, nur solange versuche < max_versuche' },
  { von: 'unbekannt', nach: 'abgebrochen', wer: ['mensch'], anlass: 'Mensch schließt den veralteten Run ab (Aufräumen); nie nachträglich „abgeschlossen“' }
];

function darfWechseln(von, nach, wer) {
  return UEBERGAENGE.some(u => u.von === von && u.nach === nach && (!wer || u.wer.includes(wer)));
}

function uebergangsTabelleMarkdown() {
  const z = ['| Von | Nach | Wer | Anlass |', '|---|---|---|---|'];
  for (const u of UEBERGAENGE) z.push('| ' + STATUS_TEXT[u.von] + ' | ' + STATUS_TEXT[u.nach] + ' | ' + u.wer.join(', ') + ' | ' + u.anlass + ' |');
  return z.join('\n');
}

// Standardfristen (Sekunden). Können je Run überschrieben werden (timeout_sek) und je Agent in der Registry.
const FRISTEN = {
  wartezeit_warteschlange: 30 * 60,        // bis ein Executor übernehmen muss
  // Wartezeit je Ausführer: Wer selbst abholt (Claude-Code-Abholer stündlich 8–20 Uhr, Hermes per Zeitplan), darf nicht nach 30 Minuten als „unbekannt“ gelten,
  // sonst gehen Aufträge über Nacht verloren (der Abholer holt nur Runs in der Warteschlange). n8n antwortet sofort und behält die kurze Frist.
  wartezeit_je_ausfuehrer: { 'claude-code': 14 * 3600, hermes: 3 * 3600 },
  timeout_sek: 15 * 60,                    // ohne Lebenszeichen in „in Arbeit“
  wartefrist_mensch: 7 * 24 * 3600,        // Rückfragen und Freigaben warten auf Menschen
  freigabe_gueltig: 24 * 3600,             // erteilte Freigabe verfällt, wenn sie nicht genutzt wird
  max_versuche: 3
};

/**
 * Prüft einen Run gegen die Fristen. Liefert null (nichts zu tun) oder { nach: 'unbekannt', grund }.
 * jetztMs: Zeitpunkt der Prüfung. Läuft bei jeder Wartung (Zeitplan) und damit auch nach einem Neustart.
 */
function fristPruefen(run, jetztMs) {
  const t = s => s ? new Date(s).getTime() : NaN;
  const alter = s => (jetztMs - t(s)) / 1000;
  const timeout = Number(run.timeout_sek) || FRISTEN.timeout_sek;
  if (run.status === 'warteschlange') {
    // Ab der letzten Zustandsänderung zählen (lebenszeichen), nicht ab dem Anlegen: ein Auftrag, der erst nach Timos Freigabe startet, hat sonst die Wartezeit schon verbraucht.
    const a = alter(run.lebenszeichen || run.erstellt);
    const frist = FRISTEN.wartezeit_je_ausfuehrer[run.ausfuehrer] || FRISTEN.wartezeit_warteschlange;
    if (a > frist) return { nach: 'unbekannt', grund: 'Kein Executor hat den Auftrag innerhalb von ' + (frist >= 7200 ? Math.round(frist / 3600) + ' Stunden' : Math.round(frist / 60) + ' Minuten') + ' übernommen.' };
  }
  if (run.status === 'in_arbeit') {
    const a = alter(run.lebenszeichen || run.gestartet || run.erstellt);
    if (a > timeout) return { nach: 'unbekannt', grund: 'Kein Lebenszeichen seit ' + Math.round(a / 60) + ' Minuten (Timeout ' + Math.round(timeout / 60) + ' Minuten). Der Run kann noch laufen, sein Ergebnis gilt aber als veraltet.' };
  }
  if (run.status === 'wartet_rueckmeldung' || run.status === 'wartet_freigabe') {
    const a = alter(run.lebenszeichen || run.gestartet || run.erstellt);
    if (a > FRISTEN.wartefrist_mensch) return { nach: 'unbekannt', grund: 'Seit ' + Math.round(a / 86400) + ' Tagen keine Antwort oder Entscheidung. Der Auftrag gilt als veraltet.' };
  }
  return null;
}

// ===== office/lib/kosten.js =====
// KI Office: Kostenstufen und Startregeln. Wer darf einen Auftrag sofort starten, wer braucht Timos Freigabe?
// Läuft identisch im n8n-Code-Knoten, im Testserver und in den Tests. Die Oberfläche bekommt die Werte in der Antwort auf „laden“ (start_regeln),
// rechnet sie aber nur für Hinweise nach; entschieden wird ausschließlich hier auf dem Server.

// ---- Stellschrauben (Timo kann sie ändern; danach `node office/n8n/bauen.mjs` und das Bündel in die Office-API einspielen) ----
const START_REGELN = {
  aktiv: true,              // Hauptschalter: false = Regel aus, alle Teammitglieder starten wie früher sofort (nichts anderes ändert sich)
  klein_max_zeichen: 600,   // „klein“: Auftragstext höchstens so lang (Zeichen)
  klein_budget_eur: 0.05,   // „klein“: Kostenlimit je Run in Euro (Standard, wenn der Auftrag kein budget_eur mitbringt; höher = nicht klein)
  tagesbudget_eur: 1,       // Tagesbudget je Person in Euro (Summe der Run-Kosten des Tages); darüber braucht jeder weitere Auftrag Timos Freigabe
  guenstige_modelle: ['deepseek-v4-flash', 'gpt-5-mini', 'claude-haiku-5-5'],  // Kostenstufe „günstig“
  teure_modelle: ['claude-opus-5-5']                                          // Kostenstufe „teuer“; alles andere ist „normal“
};
const KOSTENSTUFE_TEXT = { guenstig: 'günstig', normal: 'normal', teuer: 'teuer' };
const FREIGABE_START = { aktion: 'auftrag_start', text: 'Auftrag starten', stufe: 'start' };

/** Kostenstufe nach Modell: guenstig | normal | teuer. */
function kostenstufe(agent) {
  const m = String((agent && agent.modell) || '');
  if (START_REGELN.guenstige_modelle.includes(m)) return 'guenstig';
  if (START_REGELN.teure_modelle.includes(m)) return 'teuer';
  return 'normal';
}

/**
 * Gilt der Agent für Teammitglieder als „günstig genug“ für einen Sofortstart?
 * Das optionale Registry-Feld freigabe_noetig überschreibt die Stufe: true = immer Freigabe, false = nie wegen des Agenten.
 */
function agentSofortOk(agent) {
  if (agent && agent.freigabe_noetig === true) return false;
  if (agent && agent.freigabe_noetig === false) return true;
  return kostenstufe(agent) === 'guenstig';
}

/** Kalendertag in Berlin (JJJJ-MM-TT) für das Tagesbudget; fällt auf UTC zurück, falls die Zeitzone fehlt. */
function tagBerlin(ms) {
  try { return new Date(ms).toLocaleDateString('sv-SE', { timeZone: 'Europe/Berlin' }); } catch (e) { return new Date(ms).toISOString().slice(0, 10); }
}

/** Kosten eines Runs für das Tagesbudget: gemessene Kosten, sonst das Kostenlimit des Runs als Obergrenze. Nie gestartete Runs kosten nichts. */
function runKostenEur(run) {
  if (!run.gestartet && ['wartet_freigabe', 'abgebrochen', 'unbekannt'].includes(run.status)) return 0;
  const v = run.verbrauch;
  if (v && v.messbar && Number.isFinite(Number(v.kosten_eur))) return Number(v.kosten_eur);
  const b = Number(run.budget_eur);
  return b > 0 ? b : START_REGELN.klein_budget_eur;
}

/** Verbrauch einer Person heute (Euro): alle Runs, die sie heute angelegt hat. */
function tagesverbrauchEur(runs, mitglied_id, jetztMs) {
  const heute = tagBerlin(jetztMs);
  let s = 0;
  for (const r of runs || []) if (r.auftraggeber === mitglied_id && r.erstellt && tagBerlin(new Date(r.erstellt).getTime()) === heute) s += runKostenEur(r);
  return Math.round(s * 10000) / 10000;
}

const eur = x => (Math.round(x * 100) / 100).toFixed(2).replace('.', ',') + ' €';

/**
 * Darf der Auftrag sofort starten? mensch_ohne_admin = der Auftraggeber ist ein Mensch und nicht Admin (nur für sie gelten die Regeln).
 * Liefert { sofort, gruende: [{ code, text }], stufe, tagesverbrauch_eur }.
 */
function startPruefung({ mensch_ohne_admin, agent, auftrag, budget_eur, runs, mitglied_id, jetztMs }) {
  const stufe = kostenstufe(agent);
  const verbrauch = tagesverbrauchEur(runs, mitglied_id, jetztMs);
  if (!mensch_ohne_admin || !START_REGELN.aktiv) return { sofort: true, gruende: [], stufe, tagesverbrauch_eur: verbrauch };
  const gruende = [];
  if (!agentSofortOk(agent)) gruende.push({ code: 'agent', text: agent && agent.freigabe_noetig === true ? 'Für diesen Agenten ist in der Registry immer eine Freigabe eingestellt.' : 'Der Agent gehört zur Kostenstufe „' + KOSTENSTUFE_TEXT[stufe] + '“ (Modell ' + ((agent && agent.modell) || '?') + ').' });
  const laenge = String(auftrag || '').length;
  if (laenge > START_REGELN.klein_max_zeichen) gruende.push({ code: 'laenge', text: 'Der Auftrag ist mit ' + laenge + ' Zeichen länger als ' + START_REGELN.klein_max_zeichen + '.' });
  if (!(budget_eur <= START_REGELN.klein_budget_eur)) gruende.push({ code: 'budget', text: 'Das Kostenlimit des Auftrags (' + eur(budget_eur) + ') liegt über ' + eur(START_REGELN.klein_budget_eur) + '.' });
  if (verbrauch + budget_eur > START_REGELN.tagesbudget_eur) gruende.push({ code: 'tagesbudget', text: 'Das Tagesbudget von ' + eur(START_REGELN.tagesbudget_eur) + ' wäre überschritten (heute schon ' + eur(verbrauch) + ' plus ' + eur(budget_eur) + ').' });
  return { sofort: gruende.length === 0, gruende, stufe, tagesverbrauch_eur: verbrauch };
}

// ===== office/lib/freigabe.js =====
// KI Office: Freigaben für externe Aktionen.
// Eine Freigabe gilt nur für genau eine Aktion mit genau einem Inhalt (Hash). Ändert sich der Inhalt, braucht es eine neue Freigabe.

// Aktionen, die ohne erteilte Freigabe nie ausgeführt werden. Wer sie erteilen darf, steht in rechte.js.
const EXTERNE_AKTIONEN = {
  email_senden: { text: 'E-Mail senden', stufe: 'extern' },
  nachricht_senden: { text: 'Nachricht senden (WhatsApp, Chat)', stufe: 'extern' },
  post_veroeffentlichen: { text: 'Beitrag veröffentlichen', stufe: 'extern' },
  zahlung_ausloesen: { text: 'Zahlung auslösen', stufe: 'kritisch' },
  daten_loeschen: { text: 'Daten löschen', stufe: 'kritisch' },
  vertrag_senden: { text: 'Vertrag oder Angebot versenden', stufe: 'kritisch' },
  kalender_aendern: { text: 'Termin anlegen oder ändern', stufe: 'extern' }
};
const FREIGABE_STATUS = ['offen', 'erteilt', 'abgelehnt', 'verfallen', 'ungueltig', 'verwendet'];

const brauchtFreigabe = aktion => Object.prototype.hasOwnProperty.call(EXTERNE_AKTIONEN, String(aktion || ''));

/** Baut den Datensatz für eine neue Freigabe-Anfrage. */
function freigabeAnfordern({ freigabe_id, run_id, aktion, inhalt, vorschau, jetzt, angefordert_von }) {
  const hash = inhaltsHash(aktion, inhalt);
  return {
    freigabe_id, run_id, aktion: String(aktion), inhalt_hash: hash,
    inhalt_vorschau: String(vorschau || kurzVorschau(inhalt)).slice(0, 600),
    status: 'offen', angefordert_am: jetzt, angefordert_von: angefordert_von || null,
    entschieden_von: null, entschieden_am: null, begruendung: null,
    gueltig_bis: null, verwendet_am: null
  };
}

function kurzVorschau(inhalt) {
  if (inhalt == null) return '';
  if (typeof inhalt === 'string') return inhalt;
  try { return Object.entries(inhalt).map(([k, v]) => k + ': ' + (typeof v === 'string' ? v : JSON.stringify(v))).join(' · '); } catch (e) { return String(inhalt); }
}

/**
 * Prüft, ob eine Freigabe für genau diese Aktion und diesen Inhalt gültig ist.
 * Liefert { ok: true } oder { ok: false, grund, neu_noetig }.
 */
function freigabeGueltig(freigabe, aktion, inhalt, jetztMs) {
  if (!freigabe) return { ok: false, grund: 'Keine Freigabe vorhanden.', neu_noetig: true };
  if (freigabe.aktion !== String(aktion)) return { ok: false, grund: 'Die Freigabe gilt für eine andere Aktion (' + freigabe.aktion + ').', neu_noetig: true };
  const hash = inhaltsHash(aktion, inhalt);
  if (!gleich(freigabe.inhalt_hash, hash)) return { ok: false, grund: 'Der Inhalt wurde nach der Freigabe geändert. Es ist eine neue Freigabe nötig.', neu_noetig: true, inhalt_geaendert: true };
  if (freigabe.status === 'verwendet') return { ok: false, grund: 'Diese Freigabe wurde schon verwendet. Jede Freigabe gilt für genau eine Ausführung.', neu_noetig: true };
  if (freigabe.status !== 'erteilt') return { ok: false, grund: 'Die Freigabe ist ' + freigabe.status + ', nicht erteilt.', neu_noetig: freigabe.status !== 'offen' };
  if (freigabe.gueltig_bis && new Date(freigabe.gueltig_bis).getTime() < jetztMs) return { ok: false, grund: 'Die Freigabe ist abgelaufen.', neu_noetig: true };
  return { ok: true };
}

/** Felder für die Entscheidung eines Menschen. */
function freigabeEntscheiden(freigabe, entscheidung, von, begruendung, jetzt) {
  if (freigabe.status !== 'offen') return { fehler: 'Diese Freigabe ist nicht mehr offen (' + freigabe.status + ').' };
  if (!['erteilt', 'abgelehnt'].includes(entscheidung)) return { fehler: 'Entscheidung muss „erteilt“ oder „abgelehnt“ sein.' };
  const gueltig_bis = entscheidung === 'erteilt' ? new Date(new Date(jetzt).getTime() + FRISTEN.freigabe_gueltig * 1000).toISOString() : null;
  return { row: { status: entscheidung, entschieden_von: von, entschieden_am: jetzt, begruendung: String(begruendung || '').slice(0, 600), gueltig_bis } };
}

// ===== office/lib/rechte.js =====
// KI Office: Rechteprüfung. Läuft serverseitig im n8n-Code-Knoten (und im Testserver), nicht nur im Browser.
// Rollen aus team_mitglieder.rolle: admin | dozent | vertrieb | team | agent.

const ROLLEN_MENSCH = ['admin', 'dozent', 'vertrieb', 'team'];
const istAgent = ich => !!ich && (ich.rolle === 'agent' || ich.typ === 'agent');
const istAdmin = ich => !!ich && ich.rolle === 'admin';
const istDozent = ich => !!ich && (ich.rolle === 'admin' || ich.rolle === 'dozent');
const istMensch = ich => !!ich && !istAgent(ich);

// Was Agenten über die Office-API dürfen. Alles andere (Freigaben erteilen, Abnehmen, Abbrechen fremder Runs, Löschen, Registry) ist Menschen vorbehalten.
const AGENT_DARF = ['laden', 'auftrag_starten', 'auftrag_delegieren', 'lebenszeichen', 'ereignis', 'artefakt', 'rueckfrage', 'freigabe_anfordern', 'aktion_ausfuehren', 'run_beenden'];
// Was nur Admin darf.
const NUR_ADMIN = ['agent_speichern', 'loeschen', 'wartung', 'guthaben_setzen', 'vorschlag_entscheiden', 'agent_aktiv'];
// Wohin die Office-API einen Ausführer anstoßen darf (SSRF-Schutz, SICHERHEIT.md S6): nur eigene n8n-Adressen, nur https, nur der Webhook-Pfad.
// Weitere eigene Hosts hier ergänzen; danach `node office/n8n/bauen.mjs` und das Bündel einspielen.
const AUSFUEHRER_HOSTS = ['n8n.hm-storage.de'];
/** Ist diese Ausführer-Adresse erlaubt? https, Host aus der Liste (exakt), kein Benutzerteil, kein abweichender Port, Pfad beginnt mit /webhook/. */
function ausfuehrerUrlErlaubt(url, hosts) {
  const m = /^https:\/\/([^\/?#@:\s]+)(?::443)?(\/[^\s]*)?$/i.exec(String(url || '').trim());
  if (!m) return false;
  const host = m[1].toLowerCase(), pfad = m[2] || '/';
  return (hosts || AUSFUEHRER_HOSTS).includes(host) && pfad.startsWith('/webhook/') && !pfad.includes('..') && !pfad.includes('\\');
}
// Aktionen ohne Token (Signatur statt Token): nur die Rückmeldung des Executors.
const OHNE_TOKEN = ['rueckmeldung'];

/**
 * Projekte, die jemand sehen darf.
 * Menschen: alle Projekte (wie im Portal), außer das Mitglied hat eine Projektliste (Feld projekte, z. B. künftige Kundenzugänge).
 * Agenten: nur Projekte aus ihrer Registry-Zuordnung (office_agenten.projekte). Leer = keins.
 * Liefert null für „alle“.
 */
function sichtbareProjekte(ich, agenten) {
  if (!ich) return [];
  if (istAgent(ich)) {
    // Ein Teammitglied vom Typ agent kann mehrere Registry-Einträge ausführen (z. B. agent-claude für mehrere Rollen): Vereinigung der Projekte.
    const s = new Set();
    for (const a of (agenten || [])) if (a.mitglied_id === ich.mitglied_id || a.agent_id === ich.mitglied_id) for (const p of (Array.isArray(a.projekte) ? a.projekte : [])) s.add(p);
    return [...s];
  }
  if (Array.isArray(ich.projekte) && ich.projekte.length && !istAdmin(ich)) return ich.projekte.slice();
  return null;
}

function darfProjekt(ich, projekt, agenten) {
  const s = sichtbareProjekte(ich, agenten);
  if (s === null) return true;
  return !!projekt && s.includes(projekt);
}

/** Führt dieses Teammitglied (Typ agent) den Registry-Agenten agent_id aus? */
function fuehrtAus(ich, agentId, agenten) {
  return !!ich && (agenten || []).some(a => a.agent_id === agentId && (a.mitglied_id === ich.mitglied_id || a.agent_id === ich.mitglied_id));
}

/** Darf diese Person den Run sehen? Auftraggeber und der ausführende Agent sehen ihren Run immer. */
function darfRunSehen(ich, run, agenten) {
  if (!ich || !run) return false;
  if (run.auftraggeber === ich.mitglied_id) return true;
  if (istAgent(ich) && fuehrtAus(ich, run.agent_id, agenten)) return true;
  return darfProjekt(ich, run.projekt, agenten);
}

/** Darf diese Person den Run verändern (abbrechen, wiederholen, antworten)? */
function darfRunSteuern(ich, run, agenten) {
  if (!istMensch(ich)) return false;
  if (istDozent(ich)) return darfRunSehen(ich, run, agenten);
  return run.auftraggeber === ich.mitglied_id && darfProjekt(ich, run.projekt, agenten);
}

/** Darf diese Person eine Freigabe erteilen? Agenten nie. Kritische Aktionen nur Admin. */
function darfFreigeben(ich, freigabe, run, stufe, agenten) {
  if (!istMensch(ich)) return { ok: false, grund: 'Freigaben erteilen nur Menschen.' };
  if (!darfProjekt(ich, run && run.projekt, agenten)) return { ok: false, grund: 'Dieses Projekt siehst du nicht.' };
  if (stufe === 'kritisch' && !istAdmin(ich)) return { ok: false, grund: 'Zahlungen, Löschungen und Verträge gibt nur Timo (Admin) frei.' };
  if (freigabe && freigabe.angefordert_von === ich.mitglied_id && !istAdmin(ich)) return { ok: false, grund: 'Wer die Freigabe anfordert, darf sie nicht selbst erteilen (Vier-Augen-Prinzip).' };
  return { ok: true };
}

/** Ist diese Aktion für diese Rolle überhaupt erlaubt? */
function darfAktion(ich, aktion) {
  if (!ich) return { ok: false, code: 401, grund: 'Dein Zugang ist ungültig.' };
  if (ich.status === 'gesperrt') return { ok: false, code: 401, grund: 'Dein Zugang ist gesperrt.' };
  if (istAgent(ich) && !AGENT_DARF.includes(aktion)) return { ok: false, code: 403, grund: 'Das dürfen Agenten nicht. Erlaubt: ' + AGENT_DARF.join(', ') + '.' };
  if (NUR_ADMIN.includes(aktion) && !istAdmin(ich)) return { ok: false, code: 403, grund: 'Das darf nur Timo (Admin).' };
  return { ok: true };
}

/** Darf dieser Agent (Registry-Eintrag) dieses Werkzeug benutzen? */
function darfTool(agentReg, tool) {
  if (!agentReg) return false;
  const erlaubt = Array.isArray(agentReg.erlaubte_tools) ? agentReg.erlaubte_tools : [];
  return erlaubt.includes(String(tool));
}

// ===== office/lib/signatur.js =====
// KI Office: Signatur für den Rückmelde-Webhook (Executor → Office-API).
// Schutz gegen manipulierte Webhooks und Replay: HMAC über Zeitstempel, Nonce und Inhalts-Hash, Zeitfenster 5 Minuten, Nonce nur einmal.

const ZEITFENSTER_SEK = 300;

function nachrichtFuerSignatur(zeit, nonce, ergebnis) {
  return String(zeit) + '.' + String(nonce) + '.' + sha256(kanonisch(ergebnis === undefined ? null : ergebnis));
}

/** Erzeugt die Signatur. Der Executor ruft das mit dem run-spezifischen Rückmelde-Schlüssel auf. */
function signiere(schluessel, zeit, nonce, ergebnis) {
  return hmacSha256(schluessel, nachrichtFuerSignatur(zeit, nonce, ergebnis));
}

/**
 * Prüft eine Rückmeldung. nonceGesehen(nonce) → true, wenn die Nonce schon verwendet wurde.
 * Liefert { ok: true } oder { ok: false, grund }.
 */
function pruefeSignatur({ schluessel, zeit, nonce, ergebnis, signatur }, jetztMs, nonceGesehen) {
  if (!schluessel) return { ok: false, grund: 'Für diesen Run gibt es keinen Rückmelde-Schlüssel.' };
  const z = new Date(zeit || '').getTime();
  if (!isFinite(z)) return { ok: false, grund: 'Zeitstempel fehlt oder ist ungültig.' };
  if (Math.abs(jetztMs - z) > ZEITFENSTER_SEK * 1000) return { ok: false, grund: 'Zeitstempel außerhalb des Zeitfensters von ' + ZEITFENSTER_SEK + ' Sekunden.' };
  if (!/^[A-Za-z0-9_-]{16,64}$/.test(String(nonce || ''))) return { ok: false, grund: 'Nonce fehlt oder hat ein falsches Format (16 bis 64 Zeichen).' };
  if (nonceGesehen && nonceGesehen(String(nonce))) return { ok: false, grund: 'Diese Nonce wurde schon verwendet (Replay).' };
  const soll = signiere(schluessel, zeit, nonce, ergebnis);
  if (!gleich(soll, String(signatur || '').toLowerCase())) return { ok: false, grund: 'Signatur stimmt nicht.' };
  return { ok: true };
}

// ===== office/lib/idempotenz.js =====
// KI Office: Idempotenzschlüssel. Ein Auftrag oder eine Ausführung mit demselben Schlüssel wird nicht doppelt ausgeführt,
// sondern liefert die gespeicherte Antwort zurück. Zusätzlich sichert die Datenbank das mit einem Unique-Index ab.

const SCHLUESSEL_MUSTER = /^[A-Za-z0-9_.:-]{8,120}$/;

function schluesselGueltig(s) { return SCHLUESSEL_MUSTER.test(String(s || '')); }

/** Sucht eine frühere Antwort zu diesem Schlüssel (gleiche Art). */
function frueherGesehen(eintraege, art, schluessel) {
  return (eintraege || []).find(e => e && e.art === art && e.schluessel === schluessel) || null;
}

/** Baut den Datensatz, der die Antwort zum Schlüssel festhält. */
function merken({ art, schluessel, run_id, antwort, jetzt }) {
  return { schluessel, art, run_id: run_id || null, antwort: antwort || {}, erstellt: jetzt };
}

// ===== office/lib/postgrest.js =====
// KI Office: Schreibaufträge im PostgREST-Format (wie in der Portal-API v2) und ein kleiner In-Memory-Anwender für den Testserver.
// Ein Auftrag: { methode: 'POST'|'PATCH'|'DELETE', pfad: 'tabelle?spalte=eq.wert', body }

const enc = v => encodeURIComponent(String(v));
const neu = (tab, row) => ({ methode: 'POST', pfad: tab, body: row });
const aend = (tab, pk, id, row) => ({ methode: 'PATCH', pfad: tab + '?' + pk + '=eq.' + enc(id), body: row });
const weg = (tab, pk, id) => ({ methode: 'DELETE', pfad: tab + '?' + pk + '=eq.' + enc(id), body: {} });
const wegViele = (tab, pk, ids) => ({ methode: 'DELETE', pfad: tab + '?' + pk + '=in.(' + ids.map(enc).join(',') + ')', body: {} });

// Eindeutigkeiten, die in Supabase als Unique-Index existieren (supabase/team_office.sql). Der Testserver erzwingt sie genauso.
const UNIQUE = {
  office_runs: [['run_id'], ['idempotenzschluessel'], ['n8n_execution_id']],
  office_ereignisse: [['id'], ['idempotenz']],
  office_artefakte: [['artefakt_id']],
  office_freigaben: [['freigabe_id'], ['run_id', 'aktion', 'inhalt_hash']],
  office_idempotenz: [['schluessel']],
  office_agenten: [['agent_id']],
  office_run_schluessel: [['run_id']],
  office_kennzahlen: [['run_id']],
  office_vorschlaege: [['vorschlag_id']]
};

function filterAus(pfad) {
  const [tab, q] = String(pfad).split('?');
  const bed = [];
  if (q) for (const teil of q.split('&')) {
    const i = teil.indexOf('='); const sp = teil.slice(0, i), ausdruck = decodeURIComponent(teil.slice(i + 1));
    if (ausdruck.startsWith('eq.')) bed.push(r => String(r[sp]) === ausdruck.slice(3));
    else if (ausdruck.startsWith('in.(')) { const werte = ausdruck.slice(4, -1).split(',').map(s => decodeURIComponent(s)); bed.push(r => werte.includes(String(r[sp]))); }
    else if (ausdruck.startsWith('lt.')) bed.push(r => String(r[sp]) < ausdruck.slice(3));
    else throw new Error('Filter nicht unterstützt: ' + teil);
  }
  return { tab, passt: r => bed.every(f => f(r)) };
}

/**
 * Wendet einen Schreibauftrag auf In-Memory-Tabellen an (TESTADAPTER). Liefert { statusCode, body }.
 * Simuliert 409 bei Verletzung einer Eindeutigkeit, wie PostgREST.
 */
function wendeAn(tabellen, op, naechsteId) {
  const { tab, passt } = filterAus(op.pfad);
  if (!tabellen[tab]) tabellen[tab] = [];
  const T = tabellen[tab];
  if (op.methode === 'POST') {
    const row = { ...op.body };
    if ((tab === 'office_ereignisse' || tab === 'team_aufgaben_verlauf') && row.id == null) row.id = naechsteId ? naechsteId() : T.length + 1;
    for (const spalten of UNIQUE[tab] || []) {
      if (spalten.some(s => row[s] == null)) continue;
      if (T.some(r => spalten.every(s => String(r[s]) === String(row[s])))) return { statusCode: 409, body: { code: '23505', message: 'duplicate key value violates unique constraint (' + spalten.join(',') + ')' } };
    }
    T.push(row); return { statusCode: 201, body: {} };
  }
  if (op.methode === 'PATCH') { for (const r of T) if (passt(r)) Object.assign(r, op.body); return { statusCode: 204, body: {} }; }
  if (op.methode === 'DELETE') { tabellen[tab] = T.filter(r => !passt(r)); return { statusCode: 204, body: {} }; }
  return { statusCode: 405, body: { message: 'Methode ' + op.methode } };
}

// ===== office/lib/kennzahlen.js =====
// KI Office: Kennzahlen je Run und je Agent. Reine Funktionen ohne Abhängigkeiten, damit derselbe Code
// in der Oberfläche (Kopie docs/office/js/kennzahlen.js, erzeugt von office/n8n/bauen.mjs) und im Server-Bündel läuft.
// Grundsätze:
//  - Gemessen ist nur, was der Ausführer mit Quelle gemeldet hat. Alles andere ist „geschätzt“ (mit Basis) oder „unbekannt“, nie stillschweigend 0 €.
//  - Keine Personendaten: Eine Kennzahlzeile enthält Agent, Raum, Modell, Zahlen und feste Kategorien. Kein Auftraggeber, kein Freitext, kein Projektname.
//  - Fachlich bewertet wird nur von Menschen (abgenommen / zurückgewiesen); die Auswertung zählt das, sie urteilt nicht selbst über Inhalte.

const KENNZAHLEN_TAGE = 28;       // Auswertungsfenster: vier Wochen
const KENNZAHLEN_WOCHEN = 4;      // Trend: vier Wochenscheiben, älteste zuerst
const KZ_TAG_MS = 86400000;
const kzZeit = s => { const t = s ? new Date(s).getTime() : NaN; return Number.isFinite(t) ? t : null; };
const kzRund = (x, stellen) => { const f = Math.pow(10, stellen); return Math.round(x * f) / f; };
const kzZahl = x => (x !== null && x !== undefined && x !== '' && Number.isFinite(Number(x)) && Number(x) >= 0) ? Number(x) : null;

// ---- Stellschrauben der Schätzung (Timo kann sie ändern; danach `node office/n8n/bauen.mjs` und das Bündel einspielen) ----
// Listenpreise in US-Dollar je 1 Mio. Token [Eingabe, Ausgabe], Stand 03.11.2026. Modelle ohne Eintrag werden nicht geschätzt.
const KZ_PREISE_USD_MIO = { 'claude-haiku-5-5': [0.10, 0.50], 'claude-sonnet-5-5': [2, 10], 'claude-opus-5-5': [4, 20], 'gpt-5-mini': [0.25, 2] };
const KZ_USD_IN_EUR = 0.92;
const KZ_ZEICHEN_JE_TOKEN = 3.5;   // deutsche Texte: grob 3,5 Zeichen je Token
const KZ_EINGABE_FAKTOR = 4;       // grobe Annahme: Ein Agent liest etwa viermal so viel, wie er schreibt (Auftrag, Kontext, Quellen)
// Ausführer, die ein Modell benutzen, den Verbrauch aber nicht selbst melden können: nur für sie wird aus der Textlänge geschätzt.
// n8n-Ausführer melden entweder selbst oder arbeiten ohne Modell (Verwaltungs-Status, Orchestrierer): dort bleibt es bei „unbekannt“.
const KZ_SCHAETZ_AUSFUEHRER = ['claude-code', 'codex', 'hermes'];

const ERGEBNIS_TYPEN = ['text', 'dossier', 'bericht', 'code', 'workflow', 'medien', 'plan', 'pruefung', 'sonstiges'];
const ERGEBNIS_TYP_TEXT = { text: 'Text', dossier: 'Dossier', bericht: 'Bericht', code: 'Code', workflow: 'Workflow', medien: 'Medien', plan: 'Plan', pruefung: 'Prüfung', sonstiges: 'Sonstiges', ohne: 'ohne Ergebnis' };
const KZ_TYP_AUS_ARTEFAKT = { notiz: 'text', text: 'text', bericht: 'bericht', commit: 'code', datei: 'sonstiges', link: 'sonstiges' };

// Wirkungsfelder je Raum (= Rolle des Agenten): was am Ende zählt. Nur ganze Zahlen, eingetragen vom Ausführer oder von dem Menschen, der abnimmt.
const WIRKUNG_FELDER = {
  Vertrieb: [{ feld: 'dossiers', text: 'Dossiers' }, { feld: 'firmen', text: 'qualifizierte Firmen' }, { feld: 'termine', text: 'Termine' }],
  Marketing: [{ feld: 'texte_freigegeben', text: 'Texte freigegeben' }, { feld: 'veroeffentlicht', text: 'veröffentlicht' }],
  Akademie: [{ feld: 'lektionen', text: 'Lektionen fertig' }, { feld: 'kurspruefungen', text: 'Kursprüfungen' }],
  Kundenprojekte: [{ feld: 'workflows', text: 'Workflows geliefert' }, { feld: 'reviews', text: 'Reviews' }],
  Verwaltung: [{ feld: 'berichte', text: 'Berichte' }, { feld: 'pruefungen', text: 'Prüfungen' }]
};
const WIRKUNG_MAX = 100000;

/**
 * Modellname für die Kennzahlzeile. Der Ausführer meldet ihn als freien Text; in die Zeile kommt er nur, wenn er in der Preistabelle steht
 * oder dem Modell der Registry entspricht. Alles andere wird zu „sonstiges“: So kann über dieses Feld kein Name und kein Fremdtext in die Kennzahlen gelangen.
 */
function kennzahlModell(gemeldet, registry) {
  const g = String(gemeldet || ''), r = String(registry || '');
  const bekannt = m => !!m && (Object.prototype.hasOwnProperty.call(KZ_PREISE_USD_MIO, m) || m === 'deepseek-v4-flash');
  if (bekannt(g)) return g;
  if (bekannt(r)) return r;
  return g || r ? 'sonstiges' : null;
}

/** Prüft eine Wirkungsmeldung gegen die Felder des Raums. Liefert { wirkung } (nur bekannte Felder, ganze Zahlen) oder { fehler }. */
function wirkungPruefen(raum, eingabe) {
  const felder = WIRKUNG_FELDER[raum] || [];
  if (eingabe === null || eingabe === undefined) return { wirkung: {} };
  if (typeof eingabe !== 'object' || Array.isArray(eingabe)) return { fehler: 'wirkung muss ein Objekt aus Feld und Zahl sein.' };
  const wirkung = {};
  for (const [k, v] of Object.entries(eingabe)) {
    if (!felder.some(f => f.feld === k)) return { fehler: 'Unbekanntes Wirkungsfeld „' + String(k).slice(0, 40) + '“ für den Raum ' + (raum || '?') + '. Erlaubt: ' + (felder.map(f => f.feld).join(', ') || 'keins') + '.' };
    if (v === null || v === '' || v === undefined) continue;
    const n = typeof v === 'number' ? v : (typeof v === 'string' && /^[0-9]{1,6}$/.test(v.trim()) ? Number(v.trim()) : NaN);   // keine Wahrheitswerte, keine Listen
    if (!Number.isInteger(n) || n < 0 || n > WIRKUNG_MAX) return { fehler: 'Wirkung „' + k + '“ muss eine ganze Zahl zwischen 0 und ' + WIRKUNG_MAX + ' sein.' };
    wirkung[k] = n;
  }
  return { wirkung };
}

/** Kosten in Euro aus Tokenzahlen und Preistabelle, oder null, wenn das Modell keinen Preis hat. */
function kostenAusToken(modell, tokens_ein, tokens_aus) {
  const p = KZ_PREISE_USD_MIO[String(modell || '')];
  if (!p) return null;
  return kzRund(((Number(tokens_ein) || 0) * p[0] + (Number(tokens_aus) || 0) * p[1]) / 1e6 * KZ_USD_IN_EUR, 4);
}

/** Grobe Schätzung aus der Textlänge: Ausgabe = Zeichen der Ergebnisse, Eingabe = Auftrag plus KZ_EINGABE_FAKTOR × Ausgabe. Null, wenn kein Preis bekannt ist. */
function kostenSchaetzen(modell, auftrag_zeichen, ergebnis_zeichen) {
  if (!KZ_PREISE_USD_MIO[String(modell || '')]) return null;
  const aus = Math.ceil((Number(ergebnis_zeichen) || 0) / KZ_ZEICHEN_JE_TOKEN);
  const ein = Math.ceil((Number(auftrag_zeichen) || 0) / KZ_ZEICHEN_JE_TOKEN) + KZ_EINGABE_FAKTOR * aus;
  if (!(ein + aus > 0)) return null;
  return { tokens_ein: ein, tokens_aus: aus, kosten_eur: kostenAusToken(modell, ein, aus) };
}

/** Gemeldete Kosten eines Runs: { eur, art: 'gemessen' | 'geschätzt' } oder null, wenn der Ausführer nichts gemeldet hat. */
function runKostenGemeldet(run) {
  const v = run && run.verbrauch;
  if (!v || v.messbar !== true || v.kosten_eur == null) return null;
  const eur = Number(v.kosten_eur);
  if (!Number.isFinite(eur) || eur < 0) return null;
  return { eur, art: v.kosten_art === 'gemessen' ? 'gemessen' : 'geschätzt' };
}

/** Zeitpunkt, zu dem ein Run für die Auswertung zählt: Ende, sonst Start, sonst Anlage. */
function runStichzeit(run) { return kzZeit(run.beendet) || kzZeit(run.gestartet) || kzZeit(run.erstellt); }

/** Dauer eines beendeten Runs in Minuten (Start bis Ende) oder null. */
function runDauerMin(run) {
  const a = kzZeit(run.gestartet), b = kzZeit(run.beendet);
  return a !== null && b !== null && b >= a ? kzRund((b - a) / 60000, 1) : null;
}

const KZ_ENDE = ['abgeschlossen', 'fehlgeschlagen', 'abgebrochen', 'unbekannt'];
/** Ist dieser Run für die Kennzahlen ein gelaufener, beendeter Lauf? Nie gestartete (abgelehnte, zurückgezogene) Aufträge zählen nicht. */
function kennzahlFaehig(run) { return !!run && KZ_ENDE.includes(run.status) && (!!run.gestartet || run.status === 'abgeschlossen' || run.status === 'fehlgeschlagen'); }

/**
 * Die Kennzahlzeile eines beendeten Runs (Form der Tabelle office_kennzahlen). agent = Registry-Eintrag, artefakte = Artefakte dieses Runs.
 * Kosten in dieser Reihenfolge: 1) vom Ausführer gemeldet (gemessen mit Quelle, sonst geschätzt), 2) Token gemeldet → Preistabelle (geschätzt),
 * 3) Ausführer ohne eigene Meldung → Schätzung aus der Textlänge (geschätzt), 4) sonst unbekannt.
 */
function kennzahlZeile(run, agent, artefakte, jetztIso) {
  const A = (artefakte || []).filter(a => a && a.run_id === run.run_id);
  const v = (run.verbrauch && run.verbrauch.messbar === true) ? run.verbrauch : null;
  const modell = kennzahlModell(v && v.modell, agent && agent.modell);
  const ausfuehrer = run.ausfuehrer || (agent && agent.ausfuehrer) || null;
  let tokens_ein = v ? kzZahl(v.tokens_ein) : null, tokens_aus = v ? kzZahl(v.tokens_aus) : null;
  let kosten_eur = null, kosten_art = 'unbekannt', kosten_basis = null;
  const gemeldet = runKostenGemeldet(run);
  if (gemeldet) { kosten_eur = kzRund(gemeldet.eur, 4); kosten_art = gemeldet.art === 'gemessen' ? 'gemessen' : 'geschaetzt'; kosten_basis = 'ausfuehrer'; }
  else if (v && (tokens_ein || tokens_aus)) { const k = kostenAusToken(modell, tokens_ein, tokens_aus); if (k !== null) { kosten_eur = k; kosten_art = 'geschaetzt'; kosten_basis = 'preistabelle'; } }
  else if (KZ_SCHAETZ_AUSFUEHRER.includes(ausfuehrer) && (run.status === 'abgeschlossen' || run.status === 'fehlgeschlagen')) {
    const zeichen = String(run.zusammenfassung || '').length + A.reduce((s, a) => s + (Number(a.groesse) > 0 ? Number(a.groesse) : String(a.zusammenfassung || '').length), 0);
    const s = kostenSchaetzen((agent && agent.modell) || modell, String(run.auftrag || '').length, zeichen);
    if (s && s.kosten_eur !== null) { tokens_ein = s.tokens_ein; tokens_aus = s.tokens_aus; kosten_eur = s.kosten_eur; kosten_art = 'geschaetzt'; kosten_basis = 'textlaenge'; }
  }
  const d = runDauerMin(run);
  const typ = ERGEBNIS_TYPEN.includes(run.ergebnis_typ) ? run.ergebnis_typ : (A.length ? (KZ_TYP_AUS_ARTEFAKT[A[A.length - 1].art] || 'sonstiges') : (run.status === 'abgeschlossen' ? 'sonstiges' : 'ohne'));
  const raum = (agent && agent.raum) || null;
  const w = wirkungPruefen(raum, run.wirkung);
  return {
    run_id: run.run_id, agent_id: run.agent_id, raum, ausfuehrer, modell, status: run.status,
    beendet: run.beendet || run.lebenszeichen || run.erstellt || jetztIso || null, dauer_sek: d === null ? null : Math.round(d * 60),
    tokens_ein: tokens_ein === null ? null : Math.round(tokens_ein), tokens_aus: tokens_aus === null ? null : Math.round(tokens_aus),
    kosten_eur, kosten_art, kosten_basis, ergebnis_typ: typ, ergebnisse: A.length,
    abnahme: run.abgenommen === true ? 'abgenommen' : run.abgenommen === false ? 'zurueckgewiesen' : 'offen',
    wirkung: w.wirkung || {}, versuche: Number(run.versuche) || 1, geaendert: jetztIso || null
  };
}

/**
 * Kennzahlen eines Agenten aus Kennzahlzeilen über das Fenster (Standard 28 Tage bis jetztMs).
 * ergebnisse = technisch abgeschlossene Läufe; abgenommen / zurueck = fachliche Entscheidung eines Menschen; offen = noch nicht entschieden.
 * kosten_eur = gemessene plus geschätzte Kosten aller Läufe im Fenster (auch der fehlgeschlagenen, sie haben auch gekostet); kosten_unbekannt = Läufe ohne Wert.
 * kosten_je_abgenommen = kosten_eur / abgenommen, nur wenn es abgenommene Ergebnisse und mindestens einen Kostenwert gibt.
 * trend = Kosten je abgenommenem Ergebnis je Wochenscheibe (älteste zuerst), null wo nichts abgenommen wurde.
 */
function kennzahlenAusZeilen(zeilen, agent_id, jetztMs, tage) {
  const fenster = (Number(tage) > 0 ? Number(tage) : KENNZAHLEN_TAGE) * KZ_TAG_MS;
  const von = jetztMs - fenster, bis = jetztMs + 60000;   // eine Minute Toleranz für abweichende Uhren
  const Z = (zeilen || []).filter(z => z && z.agent_id === agent_id).filter(z => { const t = kzZeit(z.beendet); return t !== null && t > von && t <= bis; });
  const fertig = Z.filter(z => z.status === 'abgeschlossen');
  const abgenommen = fertig.filter(z => z.abnahme === 'abgenommen').length, zurueck = fertig.filter(z => z.abnahme === 'zurueckgewiesen').length;
  let gemessen = 0, geschaetzt = 0, nGemessen = 0, nGeschaetzt = 0;
  for (const z of Z) { const k = kzZahl(z.kosten_eur); if (k === null || z.kosten_art === 'unbekannt') continue; if (z.kosten_art === 'gemessen') { gemessen += k; nGemessen++; } else { geschaetzt += k; nGeschaetzt++; } }
  const mitWert = nGemessen + nGeschaetzt, kosten = gemessen + geschaetzt;
  const dauern = fertig.map(z => kzZahl(z.dauer_sek)).filter(x => x !== null).sort((a, b) => a - b);
  const bewertet = abgenommen + zurueck;
  const scheibe = fenster / KENNZAHLEN_WOCHEN, trend = [];
  for (let i = 0; i < KENNZAHLEN_WOCHEN; i++) {
    const a = von + i * scheibe, b = i === KENNZAHLEN_WOCHEN - 1 ? bis : a + scheibe;
    const S = Z.filter(z => { const t = kzZeit(z.beendet); return t > a && t <= b; });
    const ok = S.filter(z => z.status === 'abgeschlossen' && z.abnahme === 'abgenommen').length;
    let k = 0, n = 0; for (const z of S) { const x = kzZahl(z.kosten_eur); if (x !== null && z.kosten_art !== 'unbekannt') { k += x; n++; } }
    trend.push(ok > 0 && n > 0 ? kzRund(k / ok, 4) : null);
  }
  const wirkung = {};
  for (const z of Z) if (z.wirkung && typeof z.wirkung === 'object') for (const [f, n] of Object.entries(z.wirkung)) if (Number.isFinite(Number(n))) wirkung[f] = (wirkung[f] || 0) + Number(n);
  const typen = {};
  for (const z of fertig) { const t = z.ergebnis_typ || 'sonstiges'; typen[t] = (typen[t] || 0) + 1; }
  return {
    agent_id, tage: fenster / KZ_TAG_MS, runs: Z.length, gelaufen: Z.length,
    ergebnisse: fertig.length, abgenommen, zurueck, offen: fertig.length - bewertet,
    fehlgeschlagen: Z.filter(z => z.status === 'fehlgeschlagen' || z.status === 'unbekannt').length,
    kosten_eur: mitWert ? kzRund(kosten, 4) : null, kosten_gemessen_eur: kzRund(gemessen, 4), kosten_geschaetzt_eur: kzRund(geschaetzt, 4),
    kosten_gemeldet: mitWert, kosten_geschaetzt: nGeschaetzt, kosten_unbekannt: Z.length - mitWert,
    kosten_je_abgenommen: abgenommen > 0 && mitWert > 0 ? kzRund(kosten / abgenommen, 4) : null,
    zurueck_quote: bewertet > 0 ? kzRund(zurueck / bewertet, 4) : null,
    dauer_min: dauern.length ? kzRund(dauern[Math.floor((dauern.length - 1) / 2)] / 60, 1) : null,
    trend, wirkung, typen
  };
}

/**
 * Kennzahlen eines Agenten. Quelle sind die Zeilen der Tabelle office_kennzahlen (opts.zeilen, vom Server); für Runs ohne Zeile
 * (Tabelle noch nicht angelegt, oder Run älter als die Tabelle) wird die Zeile aus dem Run selbst gebildet (opts.agent, opts.artefakte).
 */
function agentKennzahlen(runs, agent_id, jetztMs, tage, opts) {
  const o = opts || {};
  const tabelle = (o.zeilen || []).filter(z => z && z.agent_id === agent_id);
  const bekannt = new Set(tabelle.map(z => z.run_id));
  const ausRuns = (runs || []).filter(r => r && r.agent_id === agent_id && !bekannt.has(r.run_id) && kennzahlFaehig(r)).map(r => kennzahlZeile(r, o.agent || null, o.artefakte || [], null));
  return kennzahlenAusZeilen(tabelle.concat(ausRuns), agent_id, jetztMs, tage);
}

/** Richtung des Trends aus den letzten beiden Wochenscheiben mit Wert: 'runter' (günstiger), 'hoch' (teurer), 'gleich' oder null. */
function trendRichtung(trend) {
  const t = (trend || []).filter(x => x !== null && x !== undefined);
  if (t.length < 2) return null;
  const a = t[t.length - 2], b = t[t.length - 1];
  if (b < a - 0.005) return 'runter';
  if (b > a + 0.005) return 'hoch';
  return 'gleich';
}

// ---- Rangliste „liefert / liefert nicht“ ----
// Schwellen als Vorschlag; Timo entscheidet. Die Bewertung ist ein Hinweis aus Zahlen, nie eine automatische Handlung.
const AUSWERTUNG_SCHWELLEN = {
  kosten_je_ergebnis_max_eur: 0.5,   // höchstens so viel je fachlich abgenommenem Ergebnis
  zurueck_quote_max: 0.2,            // höchstens dieser Anteil zurückgewiesen (von den bewerteten Ergebnissen)
  mindest_bewertet: 3                // darunter: „zu wenig Daten“, kein Urteil
};
const BEWERTUNG_TEXT = { liefert: 'liefert', beobachten: 'beobachten', liefert_nicht: 'liefert nicht', zu_wenig: 'zu wenig Daten' };

/** Bewertung eines Agenten aus seinen Kennzahlen: { stufe, text, gruende: [..] }. */
function bewertung(kz, schwellen) {
  const S = Object.assign({}, AUSWERTUNG_SCHWELLEN, schwellen || {});
  const bewertet = (kz.abgenommen || 0) + (kz.zurueck || 0);
  const gruende = [];
  const eur = x => (Math.round(x * 100) / 100).toFixed(2).replace('.', ',') + ' €';
  const proz = x => Math.round(x * 100) + ' %';
  if (bewertet < S.mindest_bewertet) return { stufe: 'zu_wenig', text: BEWERTUNG_TEXT.zu_wenig, gruende: [bewertet + ' von mindestens ' + S.mindest_bewertet + ' Ergebnissen fachlich bewertet.'] };
  if (kz.zurueck_quote !== null && kz.zurueck_quote > S.zurueck_quote_max) return { stufe: 'liefert_nicht', text: BEWERTUNG_TEXT.liefert_nicht, gruende: [proz(kz.zurueck_quote) + ' zurückgewiesen (Schwelle ' + proz(S.zurueck_quote_max) + ').'] };
  if (kz.abgenommen === 0) return { stufe: 'liefert_nicht', text: BEWERTUNG_TEXT.liefert_nicht, gruende: ['Kein Ergebnis wurde abgenommen.'] };
  if (kz.kosten_je_abgenommen === null) { gruende.push('Kosten unbekannt: der Ausführer meldet keinen Verbrauch.'); return { stufe: 'beobachten', text: BEWERTUNG_TEXT.beobachten, gruende }; }
  if (kz.kosten_je_abgenommen > S.kosten_je_ergebnis_max_eur) return { stufe: 'beobachten', text: BEWERTUNG_TEXT.beobachten, gruende: [eur(kz.kosten_je_abgenommen) + ' je abgenommenem Ergebnis (Schwelle ' + eur(S.kosten_je_ergebnis_max_eur) + ').'] };
  gruende.push(eur(kz.kosten_je_abgenommen) + ' je abgenommenem Ergebnis, ' + proz(kz.zurueck_quote || 0) + ' zurückgewiesen.');
  return { stufe: 'liefert', text: BEWERTUNG_TEXT.liefert, gruende };
}

// ===== office/lib/guthaben.js =====
// KI Office: Euro-Guthaben je Agent und Vorschläge zum Skalieren, Pausieren und Auffüllen (KI Office 2.0, Paket 3).
// Läuft identisch im n8n-Code-Knoten, im Testserver und in den Tests. Durchgesetzt wird ausschließlich hier auf dem Server:
// Ein Agent mit leerem Guthaben bekommt keinen Start. Die Oberfläche zeigt nur an.
// Vorschläge sind Hinweise aus Zahlen. Nichts davon geschieht automatisch: Jede Erhöhung, jede zweite Instanz und jede Pause ist eine Entscheidung von Timo (Admin).
// Kein Krypto, keine Selbstvermehrung: Ein Agent kann sein Guthaben nicht selbst ändern und keine Kopie von sich anlegen.

// ---- Stellschrauben (Timo kann sie ändern; danach `node office/n8n/bauen.mjs` und das Bündel einspielen) ----
const GUTHABEN_REGELN = {
  knapp_ab: 0.75,                 // ab diesem verbrauchten Anteil gilt das Guthaben als knapp (orange)
  auffuellen_ab: 0.9,             // ab diesem Anteil erscheint die Karte „Guthaben auffüllen“
  reserve_je_lauf_eur: 0.05,      // laufende Aufträge reservieren ihr Kostenlimit (budget_eur), mindestens diesen Betrag
  max_monat_eur: 500              // Obergrenze für Eingaben, gegen Tippfehler
};
const VORSCHLAG_REGELN = {
  tage: 14,                        // Zeitraum der Skalierungsregel: zwei Wochen
  mindest_bewertet: 3,             // darunter kein Vorschlag
  kosten_je_ergebnis_max_eur: 0.5, // skalieren nur, wenn ein abgenommenes Ergebnis höchstens so viel kostet
  zurueck_quote_max: 0.2,          // skalieren nur bis zu dieser Zurückweisungsquote; darüber: pausieren
  ruhe_tage: 14,                   // nach einer Entscheidung kommt derselbe Vorschlag so lange nicht wieder
  erhoehen_faktor: 1.5,            // Vorschlag „Guthaben erhöhen“: bisheriges Monatsguthaben mal diesen Faktor
  auffuellen_anteil: 0.5           // Vorschlag „auffüllen“: so viel vom Monatsguthaben für den laufenden Monat dazu
};
// Startvorschlag für das Monatsguthaben nach Modell (Vorschlag aus dem Papier „KI Office 2.0“: zusammen rund 40 €). Timo übernimmt oder ändert.
const GUTHABEN_START_EUR = { 'claude-haiku-5-5': 2, 'claude-sonnet-5-5': 3, 'claude-opus-5-5': 4, 'gpt-5-mini': 2, 'deepseek-v4-flash': 2 };
const VORSCHLAG_ARTEN = { auffuellen: 'Guthaben auffüllen', pausieren: 'Agent pausieren', skalieren: 'Agent skalieren', einrichten: 'Guthaben einrichten' };

const ghRund = x => Math.round(x * 10000) / 10000;
const ghEur = x => (Math.round(Number(x) * 100) / 100).toFixed(2).replace('.', ',') + ' €';
const ghProz = x => Math.round(x * 100) + ' %';
const ghZahl = x => (x !== null && x !== undefined && x !== '' && Number.isFinite(Number(x))) ? Number(x) : null;
/** Kalendermonat in Berlin (JJJJ-MM). Das Monatsguthaben gilt je Kalendermonat und verfällt am Monatsende. */
const monatBerlin = ms => tagBerlin(ms).slice(0, 7);

/** Ist für diesen Agenten ein Monatsguthaben eingerichtet? Leer (null) = nicht eingerichtet, dann wird nichts begrenzt. */
const guthabenEingerichtet = agent => !!agent && ghZahl(agent.budget_eur_monat) !== null && Number(agent.budget_eur_monat) >= 0;

/**
 * Kennzahlzeilen eines Agenten: die Zeilen der Tabelle, ergänzt um beendete Runs ohne Zeile (aus dem Run gebildet).
 * So stimmt der Verbrauch auch für Läufe, die vor dem Anlegen der Tabelle endeten.
 */
function agentZeilen(agent, zeilen, runs, artefakte) {
  const tab = (zeilen || []).filter(z => z && z.agent_id === agent.agent_id);
  const bekannt = new Set(tab.map(z => z.run_id));
  return tab.concat((runs || []).filter(r => r && r.agent_id === agent.agent_id && !bekannt.has(r.run_id) && kennzahlFaehig(r)).map(r => kennzahlZeile(r, agent, artefakte || [], null)));
}

/**
 * Stand des Guthabens eines Agenten im laufenden Kalendermonat (Berlin). Null, wenn keins eingerichtet ist.
 * verbraucht = gemessene und geschätzte Kosten aller in diesem Monat beendeten Läufe; Läufe ohne Kostenwert zählen nicht (ohne_angabe).
 * reserviert = Kostenlimit der Aufträge, die gerade laufen oder in der Warteschlange stehen (sie haben noch keine Kosten gemeldet).
 * leer = nichts mehr übrig: Dann startet kein weiterer Auftrag, bis Timo auffüllt oder der nächste Monat beginnt.
 */
function guthabenStand(agent, zeilen, runs, artefakte, jetztMs) {
  if (!guthabenEingerichtet(agent)) return null;
  const monat = monatBerlin(jetztMs);
  const monat_eur = Number(agent.budget_eur_monat);
  const zusatz_eur = agent.budget_zusatz_monat === monat ? Math.max(0, ghZahl(agent.budget_zusatz_eur) || 0) : 0;
  let verbraucht = 0, ohne = 0, geschaetzt = 0;
  for (const z of agentZeilen(agent, zeilen, runs, artefakte)) {
    const t = z.beendet ? new Date(z.beendet).getTime() : NaN;
    if (!Number.isFinite(t) || monatBerlin(t) !== monat) continue;
    const k = ghZahl(z.kosten_eur);
    if (k === null || z.kosten_art === 'unbekannt') { ohne++; continue; }
    verbraucht += Math.max(0, k); if (z.kosten_art !== 'gemessen') geschaetzt++;
  }
  let reserviert = 0, laufend = 0;
  for (const r of runs || []) {
    if (!r || r.agent_id !== agent.agent_id || !['warteschlange', 'in_arbeit', 'wartet_rueckmeldung'].includes(r.status) && !(r.status === 'wartet_freigabe' && r.gestartet)) continue;
    reserviert += Math.max(GUTHABEN_REGELN.reserve_je_lauf_eur, ghZahl(r.budget_eur) || 0); laufend++;
  }
  const verfuegbar = monat_eur + zusatz_eur;
  const belegt = verbraucht + reserviert;
  const rest = ghRund(verfuegbar - belegt);
  const anteil = verfuegbar > 0 ? Math.min(1, belegt / verfuegbar) : 1;
  return { monat, monat_eur: ghRund(monat_eur), zusatz_eur: ghRund(zusatz_eur), verfuegbar_eur: ghRund(verfuegbar), verbraucht_eur: ghRund(verbraucht), reserviert_eur: ghRund(reserviert),
    rest_eur: Math.max(0, rest), anteil: ghRund(anteil), leer: rest <= 0, knapp: rest > 0 && anteil >= GUTHABEN_REGELN.knapp_ab, laufend, geschaetzt: geschaetzt > 0, ohne_angabe: ohne };
}

/** Text für die Ablehnung eines Starts wegen leerem Guthaben. */
function guthabenLeerText(agent, g) {
  return 'Das Guthaben von ' + ((agent && agent.name) || 'diesem Agenten') + ' für ' + g.monat + ' ist aufgebraucht (' + ghEur(g.verbraucht_eur + g.reserviert_eur) + ' von ' + ghEur(g.verfuegbar_eur) + '). Timo füllt auf oder der Agent bleibt bis zum Monatsende pausiert.';
}

/** Vorgeschlagenes Monatsguthaben für einen Agenten ohne Guthaben (nach Modell). */
const guthabenStartwert = agent => GUTHABEN_START_EUR[String((agent && agent.modell) || '')] || 3;
const ghAufrunden = x => Math.max(1, Math.ceil(x));

/**
 * Vorschläge aus den Kennzahlen der letzten zwei Wochen. Jede Karte ist ein Vorschlag, nie eine Handlung:
 *  - auffuellen: Guthaben leer oder fast leer
 *  - pausieren:  zu viele Zurückweisungen oder nichts abgenommen
 *  - skalieren:  günstig je abgenommenem Ergebnis und selten zurückgewiesen → Guthaben erhöhen oder zweite Instanz für ein Segment
 *  - einrichten: aktive Agenten ohne Monatsguthaben (eine gemeinsame Karte)
 * entscheidungen = Zeilen aus office_vorschlaege; eine Entscheidung (angenommen oder abgelehnt) lässt denselben Vorschlag ruhe_tage lang ruhen.
 */
function vorschlaege(agenten, zeilen, runs, artefakte, entscheidungen, jetztMs) {
  const R = VORSCHLAG_REGELN, out = [];
  const ruht = (art, agent_id) => (entscheidungen || []).some(e => e && e.art === art && (e.agent_id || null) === (agent_id || null) && e.entschieden_am && (jetztMs - new Date(e.entschieden_am).getTime()) < R.ruhe_tage * 86400000);
  const ohneGuthaben = [];
  for (const a of agenten || []) {
    if (!a || !a.agent_id) continue;
    const Z = agentZeilen(a, zeilen, runs, artefakte);
    const kz = kennzahlenAusZeilen(Z, a.agent_id, jetztMs, R.tage);
    const g = guthabenStand(a, zeilen, runs, artefakte, jetztMs);
    const bewertet = kz.abgenommen + kz.zurueck;
    const zahlen = { tage: R.tage, ergebnisse: kz.ergebnisse, abgenommen: kz.abgenommen, zurueck: kz.zurueck, zurueck_quote: kz.zurueck_quote, kosten_eur: kz.kosten_eur, kosten_je_abgenommen: kz.kosten_je_abgenommen, guthaben: g };
    const wartend = (runs || []).filter(r => r && r.agent_id === a.agent_id && r.status === 'wartet_freigabe' && !r.gestartet).length;
    if (a.aktiv === false) continue;                       // pausierte Agenten bekommen keine Vorschläge; reaktivieren ist eine eigene Handlung
    if (!g) ohneGuthaben.push(a);
    // Ein leeres Guthaben wird immer gemeldet (sonst stünde der Agent still, ohne dass es jemand sieht); nur die Vorwarnung „fast leer“ ruht nach einer Entscheidung.
    if (g && (g.leer || (g.anteil >= GUTHABEN_REGELN.auffuellen_ab && !ruht('auffuellen', a.agent_id)))) {
      const wert = ghAufrunden(g.monat_eur * R.auffuellen_anteil);
      out.push({ art: 'auffuellen', agent_id: a.agent_id, name: a.name, rang: g.leer ? 0 : 1, titel: a.name + ': Guthaben ' + (g.leer ? 'leer' : 'fast leer'),
        grund: ghEur(g.verbraucht_eur + g.reserviert_eur) + ' von ' + ghEur(g.verfuegbar_eur) + ' für ' + g.monat + ' verbraucht oder reserviert.' + (g.leer ? ' Neue Aufträge starten nicht.' : '') + (wartend ? ' ' + wartend + (wartend === 1 ? ' Auftrag wartet.' : ' Aufträge warten.') : '') + (kz.abgenommen ? ' In den letzten ' + R.tage + ' Tagen ' + kz.abgenommen + ' von ' + kz.ergebnisse + ' Ergebnissen abgenommen.' : ''),
        zahlen, optionen: [{ option: 'auffuellen', text: 'Für diesen Monat auffüllen', wert }] });
    }
    if (bewertet >= R.mindest_bewertet && ((kz.zurueck_quote !== null && kz.zurueck_quote > R.zurueck_quote_max) || kz.abgenommen === 0)) {
      if (!ruht('pausieren', a.agent_id)) out.push({ art: 'pausieren', agent_id: a.agent_id, name: a.name, rang: 2, titel: a.name + ' pausieren',
        grund: kz.zurueck + ' von ' + bewertet + ' bewerteten Ergebnissen zurückgewiesen (' + ghProz(kz.zurueck_quote || 0) + ', Schwelle ' + ghProz(R.zurueck_quote_max) + ') in ' + R.tage + ' Tagen.' + (kz.kosten_eur != null ? ' Kosten in dieser Zeit: ' + ghEur(kz.kosten_eur) + '.' : ''),
        zahlen, optionen: [{ option: 'pausieren', text: 'Pausieren, bis du ihn wieder einschaltest' }] });
    } else if (bewertet >= R.mindest_bewertet && kz.kosten_je_abgenommen !== null && kz.kosten_je_abgenommen <= R.kosten_je_ergebnis_max_eur && (kz.zurueck_quote || 0) <= R.zurueck_quote_max) {
      if (!ruht('skalieren', a.agent_id)) {
        const neu = ghAufrunden((g ? g.monat_eur : guthabenStartwert(a)) * R.erhoehen_faktor);
        out.push({ art: 'skalieren', agent_id: a.agent_id, name: a.name, rang: 3, titel: a.name + ' skalieren',
          grund: kz.abgenommen + ' von ' + bewertet + ' bewerteten Ergebnissen abgenommen (' + ghProz(kz.zurueck_quote || 0) + ' zurückgewiesen), ' + ghEur(kz.kosten_je_abgenommen) + ' je abgenommenem Ergebnis in ' + R.tage + ' Tagen. Beide Werte liegen unter der Schwelle.',
          zahlen, optionen: [{ option: 'guthaben', text: 'Monatsguthaben erhöhen', wert: neu }, { option: 'instanz', text: 'Zweite Instanz für ein Segment anlegen', wert: g ? g.monat_eur : guthabenStartwert(a) }] });
      }
    }
  }
  if (ohneGuthaben.length && !ruht('einrichten', null)) {
    const werte = {}; let summe = 0; for (const a of ohneGuthaben) { werte[a.agent_id] = guthabenStartwert(a); summe += werte[a.agent_id]; }
    out.push({ art: 'einrichten', agent_id: null, name: '', rang: 4, titel: 'Guthaben einrichten für ' + ohneGuthaben.length + (ohneGuthaben.length === 1 ? ' Agenten' : ' Agenten'),
      grund: ohneGuthaben.length + ' aktive Agenten haben noch kein Monatsguthaben und sind damit nicht begrenzt. Vorschlag nach Modell: zusammen ' + ghEur(summe) + ' im Monat.',
      zahlen: { werte, summe_eur: summe }, optionen: [{ option: 'einrichten', text: 'Vorschlag übernehmen', wert: summe }] });
  }
  return out.sort((x, y) => x.rang - y.rang || String(x.name).localeCompare(String(y.name)));
}

// ===== office/lib/verarbeitung.js =====
// KI Office: Verarbeitung einer Anfrage an die Office-API.
// Läuft identisch im n8n-Code-Knoten „Anfrage prüfen“ (TEAM: Office-API), im lokalen Testserver und in den Tests.
// Eingabe: { body, D, jetzt, zufall, quelle }  Ausgabe: { weiter: 0|1|2, code, antwort, ops, extern, ich }
//   weiter 0 = Fehler sofort melden, 1 = nur antworten (nichts schreiben), 2 = Schreibaufträge (ops) ausführen, dann antworten.
// Keine Gedankengänge, keine Prompts, keine Zugangsdaten werden gespeichert: Freitext wird gekürzt und von Schlüsselmustern bereinigt.

const RAEUME = ['Akademie', 'Marketing', 'Vertrieb', 'Kundenprojekte', 'Verwaltung'];
const MODELLE = ['claude-haiku-5-5', 'claude-sonnet-5-5', 'claude-opus-5-5', 'gpt-5-mini', 'deepseek-v4-flash'];
const AUSFUEHRER = ['n8n', 'claude-code', 'codex', 'hermes'];
const EREIGNIS_ARTEN = ['schritt', 'tool', 'quelle', 'fehler', 'wiederholung', 'hinweis', 'status', 'rueckfrage', 'antwort', 'freigabe', 'artefakt', 'abnahme', 'entscheidung'];
const ARTEFAKT_ARTEN = ['text', 'datei', 'link', 'commit', 'notiz', 'bericht'];
const RUN_MARKER = id => '[run:' + id + ']';

const GEHEIMNIS_MUSTER = [/sk-[A-Za-z0-9_-]{16,}/g, /eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{10,}(\.[A-Za-z0-9_-]{10,})?/g, /gh[pousr]_[A-Za-z0-9]{20,}/g, /\b[a-f0-9]{32,64}\b/g, /(Bearer\s+)[A-Za-z0-9._-]{16,}/gi, /(passwor[dt]|kennwort|api[_-]?key|secret)\s*[:=]\s*\S+/gi];
/** Entfernt Zugangsdaten-Muster aus Freitext (Datensparsamkeit, Log-Hygiene). */
function bereinige(text) {
  let s = String(text ?? '').replace(/[\u0000-\u0008\u000B-\u001F]/g, '');
  for (const m of GEHEIMNIS_MUSTER) s = s.replace(m, (ganz, p1) => (p1 && /bearer/i.test(ganz) ? p1 : '') + '[entfernt]');
  return s;
}
const txt = (v, n) => bereinige(v).trim().slice(0, n);
const klein = (obj, maxZeichen) => {
  // Objekt datensparsam: nur einfache Werte, Strings bereinigt, insgesamt begrenzt
  const o = {};
  if (obj && typeof obj === 'object' && !Array.isArray(obj)) for (const [k, v] of Object.entries(obj).slice(0, 40)) {
    if (v == null) continue;
    o[String(k).slice(0, 60)] = typeof v === 'string' ? txt(v, 1000) : (typeof v === 'number' || typeof v === 'boolean') ? v : txt(JSON.stringify(v), 1000);
  }
  let s = JSON.stringify(o);
  if (s.length > maxZeichen) return { gekuerzt: true, text: s.slice(0, maxZeichen) };
  return o;
};
/** Woran die Startfreigabe gebunden ist: Agent, Projekt und Auftragstext des Runs (Hash über kanonisches JSON, siehe hash.js). */
const startInhalt = run => ({ agent_id: run.agent_id, projekt: run.projekt, auftrag: run.auftrag });
