  const raus = (code, fehler, extra) => ({ weiter: 0, code, antwort: Object.assign({ ok: false, fehler }, extra || {}) });
  const aktion = String(b.aktion || '');
  const d = (b.daten && typeof b.daten === 'object') ? b.daten : {};

