        ops.push(ereignis(eltern.run_id, 'tool', 'Teilauftrag delegiert an ' + reg.name + ': ' + auftrag.slice(0, 120), { kind_run_id: run_id, agent_id: reg.agent_id, projekt, team_id }, { tool: 'auftrag_delegieren' }));
