    start_regeln: Object.assign({}, START_REGELN, { kostenstufe_text: KOSTENSTUFE_TEXT, heute_verbraucht_eur: istAgent(ich) ? 0 : tagesverbrauchEur(alleRuns, ich.mitglied_id, new Date(o.jetzt || Date.now()).getTime()), startet_sofort: istAgent(ich) || istAdmin(ich) || !START_REGELN.aktiv }),
    quelle: o.quelle || 'n8n', stand: o.jetzt || new Date().toISOString()
  };
}

// ===== n8n-Anbindung (TEAM: Office-API, Knoten „Anfrage prüfen“) =====
// Eingang: Webhook „Office-API“ (Body { token, aktion, daten }) oder Zeitplan (Wartung). Daten: HTTP-Knoten „Team-Daten laden“ (rpc/team_laden).
let b, ueberWebhook = true;
try { b = $('Office-API').first().json.body || {}; } catch (e) { b = { aktion: 'wartung', intern: true }; ueberWebhook = false; }
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
if (ueberWebhook && b && typeof b === 'object') delete b.intern;   // „intern“ gilt nur für den Zeitplan-Pfad, nie von außen
const D = $('Team-Daten laden').first().json || {};
const r = verarbeiten({ body: b, D, jetzt: new Date().toISOString(), quelle: 'n8n' });
return [{ json: { weiter: r.weiter, code: r.code || 200, antwort: r.antwort || { ok: false, fehler: 'Keine Antwort' }, ops: r.ops || [], extern: r.extern || null, ich: r.ich || null, intern: b.intern === true } }];

// Prüft, ob alle Schreibaufträge geklappt haben. 409 = Eindeutigkeit verletzt (doppelter Auftrag, doppelte Nonce): als Konflikt melden, nichts wird doppelt ausgeführt.
const res = $input.all().map(i => i.json);
const p = $('Anfrage prüfen').first().json;
const fehler = res.filter(r => Number(r.statusCode) >= 300);
if (fehler.length) { const f = fehler[0]; const msg = String((f.body && (f.body.message || JSON.stringify(f.body))) || f.statusCode).slice(0, 300); return [{ json: { ok: false, code: Number(f.statusCode) === 409 ? 409 : 500, fehler: (Number(f.statusCode) === 409 ? 'Doppelter Aufruf oder Konflikt: ' : 'Speichern hat nicht geklappt: ') + msg } }]; }
return [{ json: { ok: true, code: p.code || 200, antwort: p.antwort, extern: p.extern, intern: p.intern === true } }];
